async function countOf(pattern) { return sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s, i) => s + i.count, 0); }
async function mineOne(pattern) {
  const rock = sdk.findNearbyLoc(pattern);
  if (!rock) return false;
  const before = sdk.getInventory().length;
  const opt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
  await sdk.sendInteractLoc(rock.x, rock.z, rock.id, opt.opIndex);
  const t0 = Date.now();
  while (Date.now() - t0 < 6000) {
    await new Promise(r => setTimeout(r, 150));
    await bot.dismissBlockingUI();
    if (sdk.getInventory().length > before) return Date.now() - t0;
  }
  return false;
}
const t0 = Date.now();
const ms = await mineOne(/copper/i);
return { ms, copper: await countOf(/copper ore/i), mining: sdk.getSkill('Mining') };

async function invCount(pattern) { return sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s, i) => s + i.count, 0); }
async function mineUntil(pattern, want) {
  let fails = 0;
  while (await invCount(pattern) < want) {
    const rock = sdk.findNearbyLoc(pattern);
    if (!rock) { if (++fails > 4) return 'no rock'; await new Promise(r => setTimeout(r, 500)); continue; }
    const before = sdk.getInventory().length;
    const opt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
    await sdk.sendInteractLoc(rock.x, rock.z, rock.id, opt.opIndex);
    const t0 = Date.now();
    while (Date.now() - t0 < 5000) {
      await new Promise(r => setTimeout(r, 120));
      await bot.dismissBlockingUI();
      if (sdk.getInventory().length > before) break;
    }
  }
  return 'ok';
}
const t0 = Date.now();
const r1 = await mineUntil(/copper/i, 12);
const r2 = await mineUntil(/tin/i, 12);
return { r1, r2, ms: Date.now() - t0, copper: await invCount(/copper/i), tin: await invCount(/tin/i), mining: sdk.getSkill('Mining').level };

